class LmdbCountDictionaryTest {
	private static final ValueFactory VALUES = SimpleValueFactory.getInstance();

	@TempDir
	File root;

	@Test
	void aliasesDistinguishSourcesWithSameRawIdAndDoNotRetainCallerOutput() throws Exception {
		try (LmdbSailStore firstSource = openStore("first-source");
				LmdbSailStore secondSource = openStore("second-source");
				LmdbSailStore target = openStore("target")) {
			ValueStore firstValues = (ValueStore) firstSource.getValueFactory();
			ValueStore secondValues = (ValueStore) secondSource.getValueFactory();
			ValueStore targetValues = (ValueStore) target.getValueFactory();

			long firstSourceId = store(firstValues, firstValues.createIRI("urn:alias-source:", "first"));
			long secondSourceId = store(secondValues, secondValues.createIRI("urn:alias-source:", "second"));
			long firstTargetId = store(targetValues, targetValues.createIRI("urn:alias-source:", "first"));
			long secondTargetId = store(targetValues, targetValues.createIRI("urn:alias-source:", "second"));
			firstValues.commit();
			secondValues.commit();
			targetValues.commit();
			firstValues.clearCaches();
			secondValues.clearCaches();
			targetValues.clearCaches();

			assertEquals(firstSourceId, secondSourceId,
					"Independent dictionaries should allocate the same first IRI ID for different values");
			assertTrue(firstTargetId != secondTargetId, "The target dictionary must retain both distinct IRIs");

			try (StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0])) {
				ValueStore.CountReadResource firstRead = firstValues.prepareCountRead(scope);
				ValueStore.CountReadResource secondRead = secondValues.prepareCountRead(scope);
				ValueStore.CountReadResource targetRead = targetValues.prepareCountRead(scope);
				targetRead.prepareAliases();
				scope.requireStatementKeys();
				assertTrue(scope.freeze());

				LmdbCountDictionary.Ids ids = new LmdbCountDictionary.Ids();
				targetRead.reader().aliases(firstRead.reader(), firstSourceId, ids, 0);
				assertArrayEquals(new long[] { firstTargetId }, values(ids));

				ids.values[0] = Long.MIN_VALUE;
				targetRead.reader().aliases(secondRead.reader(), secondSourceId, ids, 0);
				assertArrayEquals(new long[] { secondTargetId }, values(ids),
						"An equal raw ID from another source dictionary must use that source's RDF value");

				ids.values[0] = Long.MAX_VALUE;
				targetRead.reader().aliases(firstRead.reader(), firstSourceId, ids, 0);
				assertArrayEquals(new long[] { firstTargetId }, values(ids),
						"Repeated alias lookup must return cached values, not caller-owned output storage");
			}
		}
	}

	@Test
	void aliasesReturnAllPhysicalIdsWhenTheSameIriHasMoreThanFourSplits() throws Exception {
		try (LmdbSailStore source = openStore("split-source"); LmdbSailStore target = openStore("split-target")) {
			ValueStore sourceValues = (ValueStore) source.getValueFactory();
			ValueStore targetValues = (ValueStore) target.getValueFactory();
			String iri = "urn:alias-splits:shared:item";
			long sourceId = store(sourceValues, sourceValues.createIRI(iri));
			sourceValues.commit();
			sourceValues.clearCaches();

			int[] boundaries = { 4, 8, 18, 20, 22, iri.length() };
			Set<Long> physicalIds = new LinkedHashSet<>();
			for (int boundary : boundaries) {
				IRI split = targetValues.createIRI(iri.substring(0, boundary), iri.substring(boundary));
				targetValues.clearCaches();
				physicalIds.add(store(targetValues, split));
			}
			targetValues.commit();
			targetValues.clearCaches();
			assertEquals(boundaries.length, physicalIds.size(),
					"Cache clearing must allow each legal namespace/local split to have its own stored ID");

			try (StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0])) {
				ValueStore.CountReadResource sourceRead = sourceValues.prepareCountRead(scope);
				ValueStore.CountReadResource targetRead = targetValues.prepareCountRead(scope);
				targetRead.prepareAliases();
				scope.requireStatementKeys();
				assertTrue(scope.freeze());

				LmdbCountDictionary.Ids ids = new LmdbCountDictionary.Ids();
				targetRead.reader().aliases(sourceRead.reader(), sourceId, ids, 0);
				long[] expected = physicalIds.stream().mapToLong(Long::longValue).sorted().toArray();
				assertArrayEquals(expected, sortedValues(ids));
				ids.clear();
				targetRead.reader().aliases(sourceRead.reader(), sourceId, ids, 0);
				assertArrayEquals(expected, sortedValues(ids),
						"Alias sets larger than the bounded cache must stay complete");
			}
		}
	}

	@Test
	void aliasesReuseRecursiveCustomDatatypeDependenciesAcrossNestedTripleTerms() throws Exception {
		try (LmdbSailStore source = openStore("recursive-source");
				LmdbSailStore target = openStore("recursive-target")) {
			ValueStore sourceValues = (ValueStore) source.getValueFactory();
			ValueStore targetValues = (ValueStore) target.getValueFactory();

			IRI sourceDatatype = sourceValues.createIRI("urn:custom:datatype:", "text");
			IRI targetDatatype = targetValues.createIRI("urn:custom:datatype:", "text");
			Literal sourceFirst = sourceValues.createLiteral("stored custom literal with first label", sourceDatatype);
			Literal sourceSecond = sourceValues.createLiteral("stored custom literal with second label",
					sourceDatatype);
			Literal targetFirst = targetValues.createLiteral("stored custom literal with first label", targetDatatype);
			Literal targetSecond = targetValues.createLiteral("stored custom literal with second label",
					targetDatatype);
			IRI sourceSubject = sourceValues.createIRI("urn:nested:subject:", "value");
			IRI targetSubject = targetValues.createIRI("urn:nested:subject:", "value");
			IRI sourcePredicate = sourceValues.createIRI("urn:nested:predicate:", "value");
			IRI targetPredicate = targetValues.createIRI("urn:nested:predicate:", "value");
			TripleTerm sourceInner = sourceValues.createTripleTerm(sourceSubject, sourcePredicate, sourceFirst);
			TripleTerm targetInner = targetValues.createTripleTerm(targetSubject, targetPredicate, targetFirst);
			TripleTerm sourceNested = sourceValues.createTripleTerm(sourceSubject, sourceDatatype, sourceInner);
			TripleTerm targetNested = targetValues.createTripleTerm(targetSubject, targetDatatype, targetInner);

			long sourceDatatypeId = store(sourceValues, sourceDatatype);
			long targetDatatypeId = store(targetValues, targetDatatype);
			long sourceFirstId = store(sourceValues, sourceFirst);
			long sourceSecondId = store(sourceValues, sourceSecond);
			long targetFirstId = store(targetValues, targetFirst);
			long targetSecondId = store(targetValues, targetSecond);
			long sourceNestedId = store(sourceValues, sourceNested);
			long targetNestedId = store(targetValues, targetNested);
			sourceValues.commit();
			targetValues.commit();
			sourceValues.clearCaches();
			targetValues.clearCaches();

			try (StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0])) {
				ValueStore.CountReadResource sourceRead = sourceValues.prepareCountRead(scope);
				ValueStore.CountReadResource targetRead = targetValues.prepareCountRead(scope);
				targetRead.prepareAliases();
				scope.requireStatementKeys();
				assertTrue(scope.freeze());

				LmdbCountDictionary.Ids ids = new LmdbCountDictionary.Ids();
				targetRead.reader().aliases(sourceRead.reader(), sourceFirstId, ids, 0);
				assertArrayEquals(new long[] { targetFirstId }, values(ids));
				targetRead.reader().aliases(sourceRead.reader(), sourceNestedId, ids, 0);
				assertArrayEquals(new long[] { targetNestedId }, values(ids));
				targetRead.reader().aliases(sourceRead.reader(), sourceSecondId, ids, 0);
				assertArrayEquals(new long[] { targetSecondId }, values(ids));
				targetRead.reader().aliases(sourceRead.reader(), sourceDatatypeId, ids, 0);
				assertArrayEquals(new long[] { targetDatatypeId }, values(ids));
				targetRead.reader().aliases(sourceRead.reader(), sourceFirstId, ids, 0);
				assertArrayEquals(new long[] { targetFirstId }, values(ids));
			}
		}
	}

	private LmdbSailStore openStore(String name) throws IOException {
		File directory = new File(root, name);
		Files.createDirectories(directory.toPath());
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setInlineLiterals(false);
		return new LmdbSailStore(directory, new StoreProperties(directory), config);
	}

	private static long store(ValueStore values, Value value) throws IOException {
		return values.getId(value, true);
	}

	private static long[] values(LmdbCountDictionary.Ids ids) {
		return Arrays.copyOf(ids.values, ids.size);
	}

	private static long[] sortedValues(LmdbCountDictionary.Ids ids) {
		long[] values = values(ids);
		Arrays.sort(values);
		return values;
	}
}
